import {money,sum,metrics,validate} from './finance.js';
import {periodMonths,aggregateUnits,expenseMonth,inPeriod} from './periods.js';
import {explain,reviewedPayments,recurring} from './review.js';
const $=id=>document.getElementById(id);let data,activeMonth;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=key=>new Date(key+'-15T12:00:00').toLocaleDateString('en-US',{month:'short',year:'numeric'});
const source=r=>r.source==='Bank review'?'Bank review · Nov 12':`${r.source} · row ${r.row}`;
function explanation(r){return r.source==='Bank review'?{title:r.title,detail:r.detail}:explain(r)}
function line(name,value,note='',total=false){return `<div class="statement-row ${total?'total':''}"><span>${esc(name)}${note?`<small>${esc(note)}</small>`:''}</span><strong>${esc(value)}</strong></div>`}
function render(){const mode=$('period').value,months=periodMonths(data.months,mode,activeMonth);$('month').disabled=mode==='lifetime';const units=aggregateUnits(months),latest=months.at(-1),k=metrics({units}),ending=metrics(latest||{units:[]});
 $('period-caption').textContent=mode==='month'?label(activeMonth):`${mode==='ytd'?'YTD':'Lifetime'} · ${months.length} rent months available`;
 $('statement').innerHTML=line('Scheduled rent',money(k.scheduled))+line('Rent collected',money(k.collected),'Recorded in rent sheets',true)+line('Tenant balances due',money(ending.outstanding),`Ending ${latest?label(latest.key):'period'}`)+line('Tenant credits',money(ending.credits),'Separate from balances due')+line('Expense reconciliation','In progress','See line-item ledger; no verified actual-profit total');
 const query=$('search').value.toLowerCase();const latestMap=new Map((latest?.units||[]).map(u=>[u.address+'|'+u.unit,u.balance]));$('units').innerHTML=units.filter(u=>(u.unit+' '+u.address).toLowerCase().includes(query)).map(u=>{const balance=latestMap.get(u.address+'|'+u.unit);return `<tr><td><strong>${esc(u.unit)}</strong><small>${esc(u.address)}</small></td><td class="number">${money(u.rent)}</td><td class="number">${money(u.paid)}</td><td class="number">${balance===undefined?'—':money(balance)}</td><td><span class="pill ${balance>0?'due':''}">${balance===undefined?'Not in ending roll':balance>0?'Due':balance<0?'Credit':'Settled'}</span></td></tr>`}).join('')||'<tr><td colspan="5">No matching units.</td></tr>';
 $('budget').innerHTML=data.budget.map(b=>line(b.label,money(b.amount))).join('');$('plan-net').textContent=money(sum(data.budget,'amount'));
 $('payable-rows').innerHTML=data.expenses.filter(r=>r.unpaid>0).map(r=>{const n=explain(r);return `<tr><td><strong>${esc(n.title)}</strong></td><td class="number">${money(r.unpaid)}</td><td>${esc(n.detail)}</td><td>${esc(source(r))}</td></tr>`}).join('')||'<tr><td colspan="4">No unpaid source entries. Utility status still requires independent review.</td></tr>';
 $('recurring-rows').innerHTML=recurring.map(r=>`<tr><td><strong>${esc(r[0])}</strong></td><td>${esc(r[1])}</td><td>${esc(r[2])}</td></tr>`).join('');renderExpenses();}
function expenseRow(r){const n=explanation(r);return `<tr><td>${esc(r.date||'Undated')}</td><td><details><summary>${esc(n.title)}</summary><p>${esc(n.detail)}</p></details></td><td class="number">${r.paid?money(r.paid):'—'}</td><td class="number">${r.unpaid?money(r.unpaid):'—'}</td><td>${esc(source(r))}</td></tr>`}
function renderExpenses(){const mode=$('period').value,f=$('expense-filter').value;const rows=[...data.expenses,...reviewedPayments].filter(r=>f==='all'||(f==='paid'?r.paid>0:r.unpaid>0));const dated=rows.filter(r=>inPeriod(expenseMonth(r.date),mode,activeMonth));const undated=rows.filter(r=>!expenseMonth(r.date));$('expenses').innerHTML=dated.map(expenseRow).join('')||'<tr><td colspan="5">No dated entries for this period and status.</td></tr>';$('undated-rows').innerHTML=undated.map(expenseRow).join('')||'<tr><td colspan="5">No undated entries for this status.</td></tr>';$('expense-caption').textContent=`${dated.length} dated entries · Filtered by recorded date or service-period end, not necessarily payment date. ${undated.length} undated entries are shown separately. Explanations were reviewed November 12, 2026; source amounts refresh automatically.`;}
async function refresh(){const endpoint=window.DASHBOARD_CONFIG.endpoint;$('refresh').disabled=true;try{const response=await fetch(endpoint||'data.json',{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error(`Data request failed (${response.status}).`);data=validate(await response.json());data.months.sort((a,b)=>a.key.localeCompare(b.key));activeMonth=data.months.some(m=>m.key===activeMonth)?activeMonth:data.months.at(-1).key;$('month').innerHTML=data.months.map(m=>`<option value="${esc(m.key)}">${esc(label(m.key))}</option>`).join('');$('month').value=activeMonth;render();$('sync-status').className=endpoint?'':'warning';$('sync-status').textContent=endpoint?`Spreadsheet refreshed ${new Date().toLocaleTimeString('en-US',{timeZone:'America/Chicago',hour:'numeric',minute:'2-digit'})} CT · Review notes dated Nov 12, 2026`:`Saved snapshot · ${data.asOf}`;}catch(e){$('sync-status').className='warning';$('sync-status').textContent=`Refresh failed. ${data?'Showing previously loaded records. ':''}${e.message}`;}finally{$('refresh').disabled=false;}}
$('theme').value=['system','light','dark'].includes(document.documentElement.dataset.theme)?document.documentElement.dataset.theme:'system';$('theme').addEventListener('change',e=>{document.documentElement.dataset.theme=e.target.value;try{localStorage.setItem('property-theme',e.target.value)}catch{}});
$('month').addEventListener('change',e=>{activeMonth=e.target.value;render()});$('period').addEventListener('change',()=>data&&render());$('search').addEventListener('input',()=>data&&render());$('expense-filter').addEventListener('change',()=>data&&renderExpenses());$('refresh').addEventListener('click',refresh);refresh();setInterval(()=>{if(window.DASHBOARD_CONFIG.endpoint&&!document.hidden)refresh()},window.DASHBOARD_CONFIG.refreshMilliseconds||300000);

